class Account {
    private static int created = 0;   // ek copy, poori class ki
    private final int number;         // har object ka apna
    private double balance;

    Account(double opening) {
        if (opening < 0) throw new IllegalArgumentException("negative");
        created++;
        number = 1000 + created;
        balance = opening;
    }

    int getNumber() { return number; }
    static int getCreated() { return created; }
}

public class Main {
    public static void main(String[] args) {
        Account a1 = new Account(500);
        Account a2 = new Account(0);
        Account a3 = new Account(1200);
        System.out.println(a3.getNumber() + " " + Account.getCreated());
    }
}

