class Account {
    private int balance;

    boolean deposit(int amt) {
        if (amt <= 0) return false;
        balance += amt;
        return true;
    }

    boolean withdraw(int amt) {
        if (amt > balance) return false;
        balance -= amt;
        return true;
    }

    int balance() { return balance; }
}

public class Main {
    public static void main(String[] args) {
        Account acc = new Account();
        int ok = 0;
        if (acc.deposit(300)) ok++;
        if (acc.withdraw(500)) ok++;
        if (acc.deposit(-50)) ok++;
        if (acc.withdraw(120)) ok++;
        System.out.println(ok + " " + acc.balance());
    }
}

