class Vehicle {
    int costPerKm() { return 10; }
}

class Bike extends Vehicle {
    @Override
    int costPerKm() { return 6; }
}

class Truck extends Vehicle {
    @Override
    int costPerKm() { return 25; }

    int loadCharge() { return 200; }
}

public class Main {
    public static void main(String[] args) {
        Vehicle[] fleet = { new Bike(), new Truck(), new Vehicle() };
        for (Vehicle v : fleet) {
            int cost = v.costPerKm() * 10;
            if (v instanceof Truck t) {
                cost += t.loadCharge();
            }
            System.out.println(cost);
        }
    }
}

