interface DataSource {
    int rows();

    default String describe() { return "source with " + rows() + " rows"; }
}

class CsvSource implements DataSource {
    public int rows() { return 120; }
}

abstract class Pipeline {
    final void run(DataSource src) {
        System.out.println("load: " + src.describe());
        System.out.println("clean: " + clean(src.rows()));
    }

    abstract int clean(int rows);
}

class DropNulls extends Pipeline {
    int clean(int rows) { return rows - 15; }
}

public class Main {
    public static void main(String[] args) {
        Pipeline p = new DropNulls();
        p.run(new CsvSource());
    }
}

