abstract class Job {
    private int steps = 0;

    final String run() {
        String out = start();
        for (int i = 0; i < times(); i++) {
            out += work(i);
            steps++;
        }
        return out + ":" + steps;
    }

    String start() { return "S"; }
    abstract int times();
    abstract String work(int i);
}

class Export extends Job {
    int times() { return 3; }
    String work(int i) { return i % 2 == 0 ? "e" : "o"; }

    @Override
    String start() { return "X"; }
}

public class Main {
    public static void main(String[] args) {
        Job j = new Export();
        System.out.println(j.run() + " " + j.run());
    }
}

