class Team implements Cloneable {
    String name;
    int[] scores;

    Team(String name, int[] scores) {
        this.name = name;
        this.scores = scores;
    }

    @Override
    public Team clone() throws CloneNotSupportedException {
        return (Team) super.clone();            // shallow
    }

    Team deepCopy() throws CloneNotSupportedException {
        Team t = (Team) super.clone();
        t.scores = scores.clone();              // new array
        return t;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Team orig = new Team("Red", new int[]{5, 8});
        Team shallow = orig.clone();
        Team deep = orig.deepCopy();
        shallow.scores[0] = 50;
        deep.scores[1] = 80;
        System.out.println(orig.scores[0] + " " + orig.scores[1]);
    }
}

