class InsufficientFunds extends Exception {
    InsufficientFunds(String msg) { super(msg); }
}

class Wallet {
    private int balance = 1000;

    void withdraw(int amt) throws InsufficientFunds {
        if (amt <= 0) throw new IllegalArgumentException("bad amount");
        if (amt > balance) throw new InsufficientFunds("short by " + (amt - balance));
        balance -= amt;
    }

    int balance() { return balance; }
}

public class Main {
    public static void main(String[] args) {
        Wallet w = new Wallet();
        int[] requests = {300, 900, -5};
        for (int r : requests) {
            try {
                w.withdraw(r);
                System.out.println("paid " + r);
            } catch (InsufficientFunds e) {
                System.out.println("declined: " + e.getMessage());
            } catch (IllegalArgumentException e) {
                System.out.println("invalid: " + e.getMessage());
            } finally {
                System.out.println("balance " + w.balance());
            }
        }
    }
}

