import java.util.ArrayDeque;
import java.util.Deque;

class Buffer {
    private final Deque<Integer> items = new ArrayDeque<>();
    private final int capacity = 2;

    synchronized void put(int x) throws InterruptedException {
        while (items.size() == capacity) {
            wait();                 // full: release the lock and wait
        }
        items.addLast(x);
        notifyAll();                // wake waiting consumers
    }

    synchronized int take() throws InterruptedException {
        while (items.isEmpty()) {
            wait();                 // empty: wait for a producer
        }
        int x = items.removeFirst();
        notifyAll();                // wake waiting producers
        return x;
    }
}

